function file_limit_label(int $bytes): string { if(function_exists('policy_testing_mode') && policy_testing_mode()) return 'Unlimited'; return $bytes >= intdiv(PHP_INT_MAX, 2) ? 'Unlimited' : storage_human($bytes); }
$u=current_user();$uid=(int)$u['id'];ensure_file_workspace_schema();$limits=file_plan_limits((string)$u['plan']);$used=file_user_used_bytes($uid);$trashUsageQ=db()->prepare("SELECT COALESCE(SUM(size_bytes),0) FROM file_objects WHERE user_id=? AND trashed_at IS NOT NULL AND status<>'deleted'");$trashUsageQ->execute([$uid]);$trashUsage=(int)$trashUsageQ->fetchColumn();$driver=file_storage_driver($uid);
$s=db()->prepare("SELECT f.*,l.id AS link_id,l.slug AS link_slug,l.clicks AS link_clicks,l.status AS link_status FROM file_objects f LEFT JOIN (SELECT si.file_id, MIN(sh.link_id) AS link_id FROM file_share_items si INNER JOIN file_share_links sh ON sh.id=si.share_id WHERE sh.link_id IS NOT NULL GROUP BY si.file_id) fl ON fl.file_id=f.id LEFT JOIN short_links l ON l.id=fl.link_id WHERE f.user_id=? AND f.status<>'deleted' AND f.trashed_at IS NULL ORDER BY f.created_at DESC LIMIT 500");$s->execute([$uid]);$files=$s->fetchAll();$fq=db()->prepare("SELECT folder_name,MIN(created_at) AS created_at FROM media_assets WHERE user_id=? AND name='.folder-marker' AND deleted_at IS NULL GROUP BY folder_name ORDER BY folder_name");$fq->execute([$uid]);$folders=$fq->fetchAll();
$canFolder=policy_allows($uid,'file_folder_upload',false);$canZip=policy_allows($uid,'file_zip_downloads',false);$canShare=policy_allows($uid,'file_public_share',true);$canEmail=policy_allows($uid,'file_email_share',false);$pct=min(100,round($used/max(1,$limits['storage'])*100));
